/**
 * generate-html-bundle.mjs
 *
 * Compiles src/htmlExport.ts (pure tree/layout/renderer functions) into a
 * self-contained IIFE bundle, then writes it as a TypeScript string constant
 * to src/htmlBundle.ts so the main plugin build can embed it in HTML exports.
 *
 * Run:  node generate-html-bundle.mjs
 * Or via npm:  npm run build:html
 */

import esbuild from "esbuild";
import fs from "fs";

async function main() {
  const result = await esbuild.build({
    entryPoints: ["src/htmlExport.ts"],
    bundle: true,
    external: [],        // fully self-contained — no runtime imports
    format: "iife",      // wraps in (()=>{...})() — safe to inline in <script>
    minify: true,
    target: "es2018",
    treeShaking: true,
    write: false,
    logLevel: "info",
  });

  const code = new TextDecoder().decode(result.outputFiles[0].contents);

  const ts =
    `// AUTO-GENERATED by generate-html-bundle.mjs — do not edit manually.\n` +
    `// Run "npm run build:html" to regenerate after changing tree/layout/renderer.\n` +
    `export const HTML_BUNDLE = ${JSON.stringify(code)};\n`;

  await fs.promises.writeFile("src/htmlBundle.ts", ts);
  console.log("[arbor] html bundle → src/htmlBundle.ts  (" + code.length + " bytes)");
}

main();
